import SwiftUI

// Language and Help for the staff and outings roles' Me pages. Generated by the session (Prompt 4, rule "generate
// and add"): no frame draws them for these roles, so they follow the Guardian's Language sheet (2387:2112) and Help
// (1931:936). Owner to review. They carry no policy: Help repeats what each role's documented rules already say, and
// Language offers only English, because the app has no other translation yet.

enum StaffMeCopy {
    static let language = "Language"
    static let english = "English"
    static let tamil = "தமிழ்"
    static let hindi = "हिन्दी"
    static let notYet = "Not available in this prototype"
    static let languageNote = "Only English is built. Other languages need translated text first."
    static let help = "Help"
    static let notAvailableYet = "Not available yet"
}

/// Which Me sheet is open.
enum StaffMeSheet: String, Identifiable {
    case language, help
    var id: String { rawValue }
}

/// One question and its answer.
struct StaffHelpItem: Identifiable, Hashable {
    let question: String
    let answer: String
    var id: String { question }
}

/// The Language sheet, sized to its content: English is the one available language.
struct StaffLanguageSheet: View {
    let onClose: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: MLSpacing.s12) {
            SheetHeader(title: StaffMeCopy.language, onClose: onClose)
            VStack(spacing: 0) {
                row(StaffMeCopy.english, available: true)
                row(StaffMeCopy.tamil, available: false)
                row(StaffMeCopy.hindi, available: false, isLast: true)
            }
            Text(StaffMeCopy.languageNote)
                .mlFont(.secondary)
                .foregroundStyle(MLColor.inkSecondary)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

    private func row(_ name: String, available: Bool, isLast: Bool = false) -> some View {
        HStack {
            VStack(alignment: .leading, spacing: 2) {
                Text(name).mlFont(.staffBody).foregroundStyle(available ? MLColor.ink : MLColor.inkSecondary)
                if !available {
                    Text(StaffMeCopy.notYet).mlFont(.secondary).foregroundStyle(MLColor.inkSecondary)
                }
            }
            Spacer()
            if available {
                Image(systemName: "checkmark").foregroundStyle(MLColor.ink).accessibilityHidden(true)
            }
        }
        .frame(minHeight: 56)
        .overlay(alignment: .bottom) { if !isLast { Rectangle().fill(MLColor.border).frame(height: 1) } }
        .accessibilityElement(children: .combine)
        .accessibilityAddTraits(available ? .isSelected : [])
    }
}

/// Help, as the Guardian Help frame draws it: white question cards. Sized to its content up to the large detent.
struct StaffHelpSheet: View {
    let items: [StaffHelpItem]
    let onClose: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: MLSpacing.s12) {
            SheetHeader(title: StaffMeCopy.help, onClose: onClose)
            ForEach(items) { item in
                VStack(alignment: .leading, spacing: MLSpacing.s4) {
                    Text(item.question).mlFont(.staffBody).fontWeight(.semibold).foregroundStyle(MLColor.ink)
                    Text(item.answer).mlFont(.body).foregroundStyle(MLColor.inkSecondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(MLSpacing.s16)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: MLRadius.compact, style: .continuous).fill(MLColor.canvas))
                .accessibilityElement(children: .combine)
            }
        }
    }
}

